<script setup>import { LoaderCircle, CircleAlert, SearchX } from 'lucide-vue-next'; defineProps({ loading:Boolean,error:String,empty:Boolean }); defineEmits(['retry']);</script>
<template><div v-if="loading" class="state-panel" aria-live="polite"><LoaderCircle class="spin" :size="28"/><p>กำลังโหลดข้อมูล…</p></div><div v-else-if="error" class="state-panel error" role="alert"><CircleAlert :size="28"/><p>{{ error }}</p><button class="btn outline" @click="$emit('retry')">ลองอีกครั้ง</button></div><div v-else-if="empty" class="state-panel"><SearchX :size="32"/><h3>ยังไม่มีรายการที่ตรงกับการค้นหา</h3><p>ลองเปลี่ยนเงื่อนไขหรือกลับมาใหม่อีกครั้ง</p><slot/></div></template>
